 static class LaunchPreflightTests {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  static void Assert(bool value,string reason){if(!value)throw new Exception("FAIL: "+reason);Console.WriteLine("PASS: "+reason);}
  static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static Dictionary<string,object> Check(Engine e,bool busy=false,bool running=false){var type=typeof(Engine).Assembly.GetType("PZ3D.LaunchPreflight");Assert(type!=null,"read-only launch preflight exists");try{return D(type.GetMethod("Check",new[]{typeof(Engine),typeof(bool),typeof(bool)}).Invoke(null,new object[]{e,busy,running}));}catch(TargetInvocationException ex){throw ex.InnerException;}}
  static Dictionary<string,object> Item(Dictionary<string,object> report,string id){return ((IEnumerable)report["items"]).Cast<Dictionary<string,object>>().Single(i=>(string)i["id"]==id);}
  sealed class Fixture {
   public string Root,Home,Jar;public Engine E;
   public Fixture(){Root=Path.Combine(LauncherTestPaths.Root,"preflight-"+Guid.NewGuid().ToString("N"));Home=Path.Combine(Root,"home");E=new Engine(Path.Combine(Root,"steamapps/common/ProjectZomboid"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);Directory.CreateDirectory(E.Game);Directory.CreateDirectory(Path.GetDirectoryName(E.Mods));File.WriteAllText(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture-never-executed");File.WriteAllText(Path.Combine(E.Game,"game-version.txt"),"42.0");Config("-Xmx2g");Mods();}
   public void Config(params string[] args){File.WriteAllText(E.Config,Json.Serialize(new{vmArgs=args}));}
   public void Mods(params string[] ids){File.WriteAllText(E.Mods,"VERSION = 1,\nmods\n{\n"+string.Concat(ids.Select(id=>" mod = "+id+",\n"))+"}\nmaps\n{\n}\n");}
   public void Mod(string id,string metadata=""){string path=Path.Combine(E.User,"mods",id,"42");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"mod.info"),"id="+id+"\n"+metadata);}
   public void Buddy(){File.WriteAllText(Path.Combine(E.Game,"ZombieBuddy.jar"),"fixture-loader");File.WriteAllText(Path.Combine(E.Game,"zbNative.dll"),"fixture-native");}
   public void Java(){Buddy();Config("-Xmx2g","-agentlib:zbNative","-Duser.home="+Home);Mods("ZombieBuddy","Viewpoint");string path=Path.Combine(E.Workshop,"3809306528/mods/Viewpoint");Directory.CreateDirectory(Path.Combine(path,"common"));Directory.CreateDirectory(Path.Combine(path,"42/media/java/client"));File.WriteAllText(Path.Combine(path,"common/mod.info"),"id=Viewpoint\njavaJarFile=media/java/client/Viewpoint.jar\njavaPkgName=viewpoint\n");File.WriteAllText(Path.Combine(path,"42/mod.info"),"id=Viewpoint\n");Jar=Path.Combine(path,"42/media/java/client/Viewpoint.jar");File.WriteAllText(Jar,"abc");}
   public string[] Files(){return Directory.GetFiles(Root,"*",SearchOption.AllDirectories).OrderBy(p=>p,StringComparer.Ordinal).Select(p=>p+"|"+Convert.ToBase64String(File.ReadAllBytes(p))+"|"+File.GetLastWriteTimeUtc(p).Ticks).ToArray();}
   public string[] Directories(){return Directory.GetDirectories(Root,"*",SearchOption.AllDirectories).OrderBy(p=>p,StringComparer.Ordinal).ToArray();}
  }
  static Dictionary<string,object> ReadOnly(Fixture f){var files=f.Files();var dirs=f.Directories();var report=Check(f.E);Assert(files.SequenceEqual(f.Files())&&dirs.SequenceEqual(f.Directories()),"preflight changes no bytes, timestamps or directories");return report;}
  // Break caught: clean fixtures get blocked, or preflight writes preferences/consent.
  static void Clean(){var f=new Fixture();var report=ReadOnly(f);Assert((bool)report["canLaunch"],"clean synthetic game permits a launch request");DateTime time;Assert(DateTime.TryParse((string)report["checkedUtc"],out time),"report exposes a check time");Assert(((IEnumerable)report["items"]).Cast<object>().Count()<=12,"report has bounded issue count");Assert((string)Item(report,"launch-config")["status"]=="ok","clean config is reported separately");}
  // Break caught: malformed/ambiguous JSON, old agents or absent native files get accepted.
  static void Configuration(){foreach(string json in new[]{"not-json","{\"vmArgs\":[1]}","{\"vmArgs\":[\"-Xmxno\"]}","{\"vmArgs\":[],\"vmArgs\":[\"-Xmx2g\"]}","{\"vmArgs\":[\"-javaagent:OrangeShootPresentation.jar\"]}","{\"vmArgs\":[\"-agentlib:zbNative\"]}","{\"vmArgs\":[\"-agentlib:zbNativeExtra\"]}"}){var f=new Fixture();File.WriteAllText(f.E.Config,json);var report=ReadOnly(f);Assert(!(bool)report["canLaunch"]&&(string)Item(report,"launch-config")["status"]=="error","unsafe launch configuration is blocked: "+json);}
   var huge=new Fixture();File.WriteAllText(huge.E.Config,new string(' ',2097153));Assert(!(bool)ReadOnly(huge)["canLaunch"],"oversized JSON blocked before parse");var noHeap=new Fixture();noHeap.Config();var advisory=ReadOnly(noHeap);Assert((bool)advisory["canLaunch"]&&(string)Item(advisory,"memory")["status"]=="warning","no Xmx is advisory rather than broken configuration");}
  // Break caught: readiness ignores pending recovery, task/process state or workshop maintenance.
  static void State(){foreach(string kind in new[]{"profile","buddy","workshop"}){var f=new Fixture();string path=kind=="profile"?Path.Combine(f.E.Data,"launch-sessions",LaunchProfiles.Key(f.E)+".json"):kind=="buddy"?Path.Combine(f.E.Data,"buddy-takeover.pending"):Path.Combine(f.E.Data,"workshop-rebuild.pending");if(kind=="buddy")path=BuddyPending(f.E);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,"{}");Assert(!(bool)ReadOnly(f)["canLaunch"],kind+" pending record blocks launch without recovery writes");}var clean=new Fixture();Assert(!(bool)Check(clean.E,true,false)["canLaunch"]&&!(bool)Check(clean.E,false,true)["canLaunch"],"busy and running both block launch");}
  static string BuddyPending(Engine e){return Path.Combine(e.Data,"backups","buddy-"+DlssInstaller.Hash(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(e.Game).ToUpperInvariant())).ToLowerInvariant().Substring(0,24),"pending.json");}
  // Break caught: missing dependencies or wrong order are ignored or silently auto-sorted.
  static void Dependencies(){var f=new Fixture();f.Mod("Child","require=Parent\n");f.Mods("Child");var report=ReadOnly(f);Assert(!(bool)report["canLaunch"]&&(string)Item(report,"mods")["status"]=="error","missing selected dependency blocks launch");f.Mod("Parent");f.Mods("Child","Parent");Assert(!(bool)ReadOnly(f)["canLaunch"],"default mod order must be corrected explicitly");f.Mods("Parent","Child");Assert((bool)ReadOnly(f)["canLaunch"],"valid ordered dependencies allow launch");}
  // Break caught: recorded alternate libraries are missed or incomplete evidence is called absent.
  static void KnownSources(){var f=new Fixture();string recorded=Path.Combine(f.Root,"second-library","900");Directory.CreateDirectory(Path.Combine(recorded,"mods","Remote","42"));File.WriteAllText(Path.Combine(recorded,"mods","Remote","42","mod.info"),"id=Remote\n");Directory.CreateDirectory(f.E.Data);File.WriteAllText(Path.Combine(f.E.Data,"workshop-paths.json"),Json.Serialize(new Dictionary<string,string>{{"900",recorded}}));f.Mods("Remote");Assert((bool)ReadOnly(f)["canLaunch"],"recorded alternate workshop source is inspected without registry discovery");f.Mod("UnknownMetadata");File.WriteAllText(Path.Combine(f.E.User,"mods","UnknownMetadata","42","mod.info"),new string('x',1048577));f.Mods("UnknownMetadata");var report=ReadOnly(f);Assert((bool)report["canLaunch"]&&(string)Item(report,"mods")["status"]=="warning","unreadable mod metadata is advisory unknown rather than invented missing evidence");}
  // Break caught: bounded preflight reads every large metadata file in the known inventory.
  static void MetadataBudget(){var f=new Fixture();for(int i=0;i<67;i++)f.Mod("Bulk"+i,"description="+new string('x',262000)+"\n");string recorded=Path.Combine(f.Root,"recorded-after-local","900");Directory.CreateDirectory(Path.Combine(recorded,"mods","AfterBudget","42"));File.WriteAllText(Path.Combine(recorded,"mods","AfterBudget","42","mod.info"),"id=AfterBudget\nrequire=NotSelected\ndescription="+new string('x',262000)+"\n");Directory.CreateDirectory(f.E.Data);File.WriteAllText(Path.Combine(f.E.Data,"workshop-paths.json"),Json.Serialize(new Dictionary<string,string>{{"900",recorded}}));f.Mods("AfterBudget");var report=ReadOnly(f);Assert((bool)report["canLaunch"]&&(string)Item(report,"mods")["status"]=="warning","metadata beyond the cumulative read budget stays uninspected and advisory");}
  // Break caught: preflight weakens existing BAT/Steam guards or follows a junction.
  static void Guards(){var f=new Fixture();f.Buddy();f.Config("-Xmx2g","-agentlib:zbNative");File.WriteAllText(Path.Combine(f.E.Game,"ProjectZomboid64.bat"),"java -javaagent:ZombieBuddy.jar -jar game.jar");Assert(!(bool)ReadOnly(f)["canLaunch"],"old BAT Buddy loader remains blocked");File.Delete(Path.Combine(f.E.Game,"ProjectZomboid64.bat"));string steam=Path.Combine(f.Root,"steam-client");SteamLaunchOptionsTests.Fixture(steam,42,SteamLaunchOptionsTests.Wrap("\"108600\" { \"LaunchOptions\" \"-javaagent:ZombieBuddy.jar -password secret\" }"));var e=new Engine(f.E.Game,f.E.User,f.E.Data,true,()=>SteamLaunchOptions.Read(steam,42));string report=Json.Serialize(Check(e));Assert(report.Contains("\"canLaunch\":false")&&!report.Contains("secret")&&!report.Contains(steam),"current Steam launch guard is retained without exposing private options");var link=new Fixture();string target=Path.Combine(link.Root,"actual-mods");Directory.Move(Path.GetDirectoryName(link.E.Mods),target);var start=new ProcessStartInfo("cmd.exe","/c mklink /J \""+Path.GetDirectoryName(link.E.Mods)+"\" \""+target+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(start)){string output=process.StandardOutput.ReadToEnd();string errors=process.StandardError.ReadToEnd();Assert(process.WaitForExit(5000)&&process.ExitCode==0,"synthetic junction fixture created");}string before=File.ReadAllText(Path.Combine(target,"default.txt"));Assert(!(bool)Check(link.E)["canLaunch"]&&File.ReadAllText(Path.Combine(target,"default.txt"))==before,"reparse point is rejected without following or modifying its target");}
  // Break caught: Java status starts a process to infer a default home.
  static void NoJavaProbe(){var f=new Fixture();f.Java();f.Config("-Xmx2g","-agentlib:zbNative");string java=Path.Combine(f.E.Game,"jre64","bin","java.exe");Directory.CreateDirectory(Path.GetDirectoryName(java));File.Copy(typeof(LaunchPreflightTests).Assembly.Location,java);var report=ReadOnly(f);Assert((bool)report["canLaunch"]&&(string)Item(report,"java-approvals")["status"]=="warning"&&!File.Exists(Path.Combine(f.E.Game,"preflight-java-probe.marker")),"default Java home remains advisory without starting the synthetic Java executable");}
