  // Break caught: pending consent becomes fatal/automatic or server files are invented.
  static void Approvals(){var f=new Fixture();f.Java();var report=ReadOnly(f);Assert((bool)report["canLaunch"]&&(string)Item(report,"java-approvals")["status"]=="warning"&&(string)Item(report,"java-approvals")["route"]=="java","pending current Java approvals have a direct advisory route");string store=Path.Combine(f.Home,".zombie_buddy/mod_approvals.json");Directory.CreateDirectory(Path.GetDirectoryName(store));File.WriteAllText(store,"{\"formatVersion\":2,\"mods\":[{\"jar_hash\":\"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\",\"decision\":true}]}");Assert((string)Item(ReadOnly(f),"java-approvals")["status"]=="ok","approval checks persisted decision for the current file");File.WriteAllText(f.Jar,"updated");Assert((string)Item(ReadOnly(f),"java-approvals")["status"]=="warning","changed jar requires fresh explicit consent");f.Config("-Xmx2g","-agentlib:zbNative");string serialized=Json.Serialize(ReadOnly(f));Assert(!serialized.Contains(f.Root)&&!serialized.Contains("ba7816")&&!serialized.Contains("updated"),"report exposes no private paths, hashes or Java contents");}
  // Break caught: native payload permits page-supplied targets or launch reuses stale readiness.
  static void Controller(){var f=new Fixture();ModernHostPolicy.Validate("https://orange.local/index.html","{\"id\":\"preflight\",\"action\":\"launchPreflight\",\"payload\":{}}");bool rejected=false;try{ModernHostPolicy.Validate("https://orange.local/index.html","{\"id\":\"preflight\",\"action\":\"launchPreflight\",\"payload\":{\"path\":\"secret\"}}");}catch{rejected=true;}Assert(rejected,"preflight native action rejects page-supplied paths");using(var controller=new ModernController(f.E.Game,f.E.User,f.E.Data,true)){var original=f.Files();var directories=f.Directories();Assert((bool)D(controller.Execute("launchPreflight",new Dictionary<string,object>()))["canLaunch"],"controller returns serializable preflight");Assert(original.SequenceEqual(f.Files())&&directories.SequenceEqual(f.Directories()),"controller preflight creates no journal or preferences");f.Mod("Child","require=Parent\n");f.Mods("Child");foreach(string action in new[]{"launch","profileLaunch"}){string failure="";var progress=new List<string>();controller.Progress=(v,t)=>progress.Add(t);try{controller.Execute(action,new Dictionary<string,object>{{"kind","save"},{"id","fixture"}});}catch(Exception ex){failure=ex.Message;}Assert(failure.Contains("模组")&&!failure.Contains("测试模式"),action+" reruns stale preflight at controller boundary");Assert(progress.Any(t=>t.Contains("检查启动"))&&!progress.Any(t=>t.Contains("游戏已就绪")||t.Contains("连接成功")),action+" emits an honest preflight stage");}f.Mods();foreach(string action in new[]{"launch","profileLaunch"}){string failure="";try{controller.Execute(action,new Dictionary<string,object>{{"kind","server"},{"id","fixture"}});}catch(Exception ex){failure=ex.Message;}Assert(failure.Contains("测试模式"),action+" test fixtures cannot start external processes");}}}
