  public static int Main(string[] args){try{if(args.Contains("-XshowSettings:properties")){File.WriteAllText(Path.Combine(Environment.CurrentDirectory,"preflight-java-probe.marker"),"unexpected-synthetic-probe");return 1;}Run();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
